import { FORMAT_VERSION, MAX_CHUNK_EXPANDED_BYTES, MAX_COMPRESSED_BYTES, MAX_EXPANDED_BYTES, MAX_CHUNKS } from './diagnostics-format.js';

const DB_NAME='delta-diagnostics-v1', DB_VERSION=1;
const TOTAL_BYTES=50*1024*1024, RESERVE_BYTES=20*1024*1024;
const RETENTION_MS=7*24*60*60*1000, RECEIPT_MS=30*24*60*60*1000;
const encoder=new TextEncoder();
const request=req=>new Promise((resolve,reject)=>{req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error);});
const transactionDone=tx=>new Promise((resolve,reject)=>{tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error||new Error('Storage transaction aborted'));});
function openDb(){return new Promise((resolve,reject)=>{const req=indexedDB.open(DB_NAME,DB_VERSION);req.onupgradeneeded=()=>{const db=req.result;db.createObjectStore('recordings',{keyPath:'id'});db.createObjectStore('chunks',{keyPath:['recordingId','index']});db.createObjectStore('receipts',{keyPath:'id'});};req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error);});}
async function all(db,store){const tx=db.transaction(store);const rows=await request(tx.objectStore(store).getAll());await transactionDone(tx);return rows;}
async function chunkAt(db,id,index){return request(db.transaction('chunks').objectStore('chunks').get([id,index]));}
async function put(db,store,value){const tx=db.transaction(store,'readwrite');tx.objectStore(store).put(value);await transactionDone(tx);}
async function del(db,store,key){const tx=db.transaction(store,'readwrite');tx.objectStore(store).delete(key);await transactionDone(tx);}
async function gzip(bytes){const stream=new Blob([bytes]).stream().pipeThrough(new CompressionStream('gzip'));return new Uint8Array(await new Response(stream).arrayBuffer());}
async function sha(bytes){return [...new Uint8Array(await crypto.subtle.digest('SHA-256',bytes))].map(x=>x.toString(16).padStart(2,'0')).join('');}
function base64(bytes){let result='';for(let i=0;i<bytes.length;i+=8192)result+=String.fromCharCode(...bytes.subarray(i,i+8192));return btoa(result);}
async function responseJson(response){if(!response.ok)throw new Error(response.status===404?'Upload service unavailable; recording remains on this device.':response.status===401?'Upload authorization expired; enter the key again.':`Upload failed (${response.status}); recording remains on this device.`);return response.status===204?null:response.json();}
export class DiagnosticsRecorder{
  constructor({appVersion,buildId,roadDataVersion,configuration,onChange}){Object.assign(this,{appVersion,buildId,roadDataVersion,configuration,onChange});this.db=null;this.active=null;this.pending=[];this.pendingBytes=0;this.queuedBytes=0;this.queue=Promise.resolve();this.stopPromise=null;this.stopping=false;this.status='Off by default.';this.flushTimer=setInterval(()=>{if(this.active&&!this.stopping&&this.pending.length)this.queue=this.queue.then(()=>this.flush()).catch(error=>{this.status=`Recording stopped: ${error.message}`;void this.stop();});},5000);}
  async init(){this.db=await openDb();await this.prune();const records=await all(this.db,'recordings'),valid=new Set(records.flatMap(r=>(r.chunks||[]).map(c=>`${r.id}:${c.index}`)));const tx=this.db.transaction('chunks','readwrite');await new Promise((resolve,reject)=>{const req=tx.objectStore('chunks').openKeyCursor();req.onsuccess=()=>{const cursor=req.result;if(!cursor)return resolve();if(!valid.has(`${cursor.key[0]}:${cursor.key[1]}`))cursor.delete();cursor.continue();};req.onerror=()=>reject(req.error);});await transactionDone(tx);for(const row of records)if(row.status==='recording'){row.status='interrupted';row.endedAt=row.endedAt||new Date(Math.min(Date.now(),Date.parse(row.startedAt)+2*60*60*1000)).toISOString();await put(this.db,'recordings',row);}await this.notify();}
  async prune(){const now=Date.now();for(const row of await all(this.db,'recordings'))if(now-Date.parse(row.startedAt)>RETENTION_MS)await this.delete(row.id);const receipts=(await all(this.db,'receipts')).sort((a,b)=>b.uploadedAt.localeCompare(a.uploadedAt));for(const [index,row] of receipts.entries())if(index>=100||now-Date.parse(row.uploadedAt)>RECEIPT_MS)await del(this.db,'receipts',row.id);}
  async usage(){const records=await all(this.db,'recordings');const receipts=await all(this.db,'receipts');const compressed=records.reduce((n,row)=>n+(row.chunks||[]).reduce((m,c)=>m+c.compressedBytes,0),0);const metadata=encoder.encode(JSON.stringify(records)+JSON.stringify(receipts)).byteLength;return {records,receipts,bytes:compressed+metadata};}
  async notify(){const usage=await this.usage();this.onChange?.({active:!!this.active,status:this.status,...usage});}
  async start(){if(this.active)return;await this.prune();const estimate=await navigator.storage?.estimate?.();if(estimate?.quota!=null&&estimate?.usage!=null&&estimate.quota-estimate.usage<RESERVE_BYTES)throw new Error('Device storage is too low to start; keep 20 MiB free.');const {bytes,records}=await this.usage();if(bytes>=TOTAL_BYTES||records.length>=100)throw new Error('Local recording space is full. Export or delete a recording first.');const id=crypto.randomUUID(),startedAt=new Date().toISOString();this.active={id,formatVersion:FORMAT_VERSION,appVersion:this.appVersion,buildId:this.buildId,roadDataVersion:this.roadDataVersion,configuration:this.configuration(),startedAt,endedAt:null,issue:'',eventCount:0,chunks:[],status:'recording'};this.pending=[];this.pendingBytes=0;this.nextSeq=0;if(bytes+encoder.encode(JSON.stringify(this.active)).byteLength>TOTAL_BYTES){this.active=null;throw new Error('50 MiB local storage limit reached.');}await put(this.db,'recordings',this.active);this.status='Recording on this device while the page is visible.';await this.notify();}
  capture(type,payload){if(!this.active||this.stopping||document.visibilityState!=='visible'&&!['visibility','session'].includes(type))return;if(Date.now()-Date.parse(this.active.startedAt)>=2*60*60*1000){this.status='Two-hour recording limit reached.';void this.stop();return;}const event={type,recordedAt:new Date().toISOString(),seq:this.nextSeq++,...payload};let line;try{line=JSON.stringify(event)+'\n';}catch{this.nextSeq--;return;}const size=encoder.encode(line).byteLength;if(size>MAX_CHUNK_EXPANDED_BYTES||this.queuedBytes+this.pendingBytes+size>MAX_CHUNK_EXPANDED_BYTES*2){this.status='Writer backlog or event size limit reached; recording stopped.';void this.stop();return;}this.queuedBytes+=size;this.queue=this.queue.then(async()=>{this.queuedBytes-=size;if(!this.active)return;if(this.pendingBytes+size>MAX_CHUNK_EXPANDED_BYTES)await this.flush();this.pending.push(line);this.pendingBytes+=size;if(this.pendingBytes>=MAX_CHUNK_EXPANDED_BYTES)await this.flush();}).catch(error=>{this.status=`Recording stopped: ${error.message}`;void this.stop();});}
  checkpoint(){if(!this.active||this.stopping)return;this.queue=this.queue.then(()=>this.flush()).catch(error=>{this.status=`Recording stopped: ${error.message}`;void this.stop();});}
  async flush(){if(!this.active||!this.pending.length)return;const expanded=encoder.encode(this.pending.join('')),compressed=await gzip(expanded),{bytes}=await this.usage();const estimate=await navigator.storage?.estimate?.();const recordCompressed=this.active.chunks.reduce((n,c)=>n+c.compressedBytes,0),recordExpanded=this.active.chunks.reduce((n,c)=>n+c.expandedBytes,0);if(this.active.chunks.length>=MAX_CHUNKS||recordCompressed+compressed.byteLength>MAX_COMPRESSED_BYTES||recordExpanded+expanded.byteLength>MAX_EXPANDED_BYTES||bytes+compressed.byteLength>TOTAL_BYTES||estimate?.quota!=null&&estimate?.usage!=null&&estimate.quota-estimate.usage-compressed.byteLength<RESERVE_BYTES)throw new Error('Recording limit or storage reserve reached. Earlier chunks are preserved.');const index=this.active.chunks.length,hash=await sha(compressed),meta={index,sha256:hash,compressedBytes:compressed.byteLength,expandedBytes:expanded.byteLength,eventCount:this.pending.length};const row={...this.active,chunks:[...this.active.chunks,meta],eventCount:this.active.eventCount+this.pending.length};const metadataDelta=encoder.encode(JSON.stringify(row)).byteLength-encoder.encode(JSON.stringify(this.active)).byteLength+encoder.encode(JSON.stringify(meta)).byteLength;if(bytes+compressed.byteLength+metadataDelta>TOTAL_BYTES)throw new Error('50 MiB local storage limit reached. Earlier chunks are preserved.');const tx=this.db.transaction(['chunks','recordings'],'readwrite');tx.objectStore('chunks').put({recordingId:row.id,index,data:compressed,...meta});tx.objectStore('recordings').put(row);await transactionDone(tx);this.active=row;this.pending=[];this.pendingBytes=0;await this.notify();}
  stop(interrupted=false){if(this.stopPromise)return this.stopPromise;if(!this.active)return Promise.resolve();this.stopping=true;this.stopPromise=this.finishStop(interrupted).finally(()=>{this.stopPromise=null;this.stopping=false;});return this.stopPromise;}
  async finishStop(interrupted){await this.queue;try{await this.flush();}catch(error){this.status=`Stopped: ${error.message}. Earlier chunks remain available.`;}const row=this.active;if(!row)return;row.endedAt=new Date(Math.min(Date.now(),Date.parse(row.startedAt)+2*60*60*1000)).toISOString();row.status=interrupted?'interrupted':'stopped';await put(this.db,'recordings',row);this.active=null;this.pending=[];this.pendingBytes=0;if(!this.status.startsWith('Stopped:'))this.status=interrupted?'Interrupted by page close; saved chunks remain.':'Recording stopped. Export, upload, or delete it.';await this.notify();}
  async delete(id){if(this.active?.id===id)await this.stop();const row=await request(this.db.transaction('recordings').objectStore('recordings').get(id));for(const chunk of row?.chunks||[])await del(this.db,'chunks',[id,chunk.index]);await del(this.db,'recordings',id);await this.notify();}
  async clear(){if(this.active)await this.stop();for(const row of await all(this.db,'recordings'))await this.delete(row.id);this.status='Local recordings cleared.';await this.notify();}
  async manifest(id,issue=''){const row=await request(this.db.transaction('recordings').objectStore('recordings').get(id));if(!row)throw new Error('Recording not found.');return {recordingId:row.id,formatVersion:FORMAT_VERSION,appVersion:row.appVersion,buildId:row.buildId,roadDataVersion:row.roadDataVersion,configuration:row.configuration,startedAt:row.startedAt,endedAt:row.endedAt||new Date().toISOString(),issue,eventCount:row.eventCount,chunks:row.chunks};}
  async export(id,issue=''){if(this.active?.id===id)await this.stop();const manifest=await this.manifest(id,issue),parts=[`{"manifest":${JSON.stringify(manifest)},"chunks":[`];for(const meta of manifest.chunks){const chunk=await chunkAt(this.db,id,meta.index);if(!chunk)throw new Error('A local chunk is missing; export cancelled.');parts.push(`${meta.index?',':''}{"index":${meta.index},"data":"${base64(new Uint8Array(chunk.data))}"}`);}parts.push(']}');const url=URL.createObjectURL(new Blob(parts,{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=`delta-diagnostics-${id}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);this.status='Exported a portable JSON archive with base64 gzip chunks.';await this.notify();}
  async upload(id,key,issue=''){if(this.active?.id===id)await this.stop();const row=await request(this.db.transaction('recordings').objectStore('recordings').get(id));if(!row.uploadManifest)row.uploadManifest=await this.manifest(id,issue);if(!row.uploadToken)row.uploadToken=[...crypto.getRandomValues(new Uint8Array(32))].map(x=>x.toString(16).padStart(2,'0')).join('');await put(this.db,'recordings',row);const manifest=row.uploadManifest;const tokenHeaders={'X-Upload-Token':row.uploadToken};await responseJson(await fetch('/api/diagnostics/auth',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify({key})}));const base='/api/diagnostics/recordings';const created=await responseJson(await fetch(base,{method:'POST',credentials:'same-origin',headers:{...tokenHeaders,'Content-Type':'application/json'},body:JSON.stringify({manifest})}));if(created.status!=='completed')for(const meta of manifest.chunks){const chunk=await chunkAt(this.db,id,meta.index);if(!chunk)throw new Error('A local chunk is missing; upload stopped.');const result=await responseJson(await fetch(`${base}/${encodeURIComponent(id)}/chunks/${chunk.index}`,{method:'PUT',credentials:'same-origin',headers:{...tokenHeaders,'Content-Type':'application/gzip','Content-Encoding':'gzip'},body:chunk.data}));if(result.index!==chunk.index||result.sha256!==chunk.sha256)throw new Error('Server chunk checksum differs; local recording is preserved.');}if(created.status!=='completed')await responseJson(await fetch(`${base}/${encodeURIComponent(id)}/finalize`,{method:'POST',credentials:'same-origin',headers:tokenHeaders}));const status=await responseJson(await fetch(`${base}/${encodeURIComponent(id)}/status`,{credentials:'same-origin',headers:tokenHeaders}));const actual=status.uploadedChunks;const expected=manifest.chunks.map(c=>c.index).sort((a,b)=>a-b);if(status.status!=='completed'||!Array.isArray(actual)||actual.length!==expected.length||actual.some((n,i)=>n!==expected[i])||manifest.chunks.some(c=>status.uploadedChunkChecksums?.[c.index]!==c.sha256))throw new Error('Server verification is incomplete; local recording is preserved.');await put(this.db,'receipts',{id,uploadedAt:new Date().toISOString(),eventCount:manifest.eventCount,bytes:manifest.chunks.reduce((n,c)=>n+c.compressedBytes,0)});await this.delete(id);this.status=`Upload ${id} verified; local chunks deleted. Receipt retained for 30 days.`;await this.notify();}
}
